package com.bank.tolist;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class ToListDifferenceTest {

    @Test void collectToListIsMutable() {
        List<String> list = Stream.of("A", "B").collect(Collectors.toList());
        list.add("C");
        list.sort(Comparator.reverseOrder());
        assertThat(list).containsExactly("C", "B", "A");
    }

    @Test void toListIsUnmodifiable() {
        List<String> list = Stream.of("A", "B").toList();
        assertThatThrownBy(() -> list.add("C")).isInstanceOf(UnsupportedOperationException.class);
        assertThatThrownBy(() -> list.sort(null)).isInstanceOf(UnsupportedOperationException.class);
    }

    @Test void collectToListAllowsNulls() {
        List<String> list = Stream.of("A", null, "B").collect(Collectors.toList());
        assertThat(list).containsExactly("A", null, "B");
    }

    @Test void toListRejectsNulls() {
        assertThatThrownBy(() -> Stream.of("A", null, "B").toList())
            .isInstanceOf(NullPointerException.class);
    }

    @Test void workaroundForMutableFromToList() {
        List<String> mutable = new ArrayList<>(Stream.of("A", "B").toList());
        mutable.add("C");
        assertThat(mutable).hasSize(3);
    }
}
