package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class ToListTest {

    @Test
    void streamToListUnmodifiableVsCollectorsMutable() {
        List<Integer> readOnly = Stream.of(1, 2, 3).toList();        // Java 16, unmodifiable
        assertThatThrownBy(() -> readOnly.add(4))
            .isInstanceOf(UnsupportedOperationException.class);

        List<Integer> mutable = Stream.of(1, 2, 3)
            .collect(Collectors.toList());                           // typically ArrayList
        mutable.add(4);                                              // allowed
        assertThat(mutable).containsExactly(1, 2, 3, 4);
    }
}
